		intent?.category?.descriptor
			?.code !==
		"CULTURE_HERITAGE"
	) {
		return {
			valid: false,
			code: 400,
			description:
				"category.descriptor.code must be CULTURE_HERITAGE",
		};
	}

	const fulfillment =
		intent?.fulfillment;

	if (!fulfillment) {
		return {
			valid: false,
			code: 400,
			description:
				"Missing fulfillment",
		};
	}

	if (
		fulfillment?.vehicle
			?.category !== "SITE"
	) {
		return {
			valid: false,
			code: 400,
			description:
				"vehicle.category must be SITE",
		};
	}

	const stops =
		fulfillment?.stops || [];

	if (
		!Array.isArray(stops) ||
		stops.length === 0
	) {
		return {
			valid: false,
			code: 400,
			description:
				"Missing fulfillment.stops",
		};
	}

	const startStop = stops.find(
		(stop) => stop?.type === "START"
	);

	if (!startStop) {
		return {
			valid: false,
			code: 400,
			description:
				"START stop missing",
		};
	}

	if (
		!startStop?.location?.city
			?.code
	) {
		return {
			valid: false,
			code: 400,
			description:
				"Missing city code",
		};
	}

	const timeRange =
		startStop?.time?.range;

	if (
		!timeRange?.start ||
		!timeRange?.end
	) {
		return {
			valid: false,
			code: 400,
			description:
				"Missing time range",
		};
	}



	const tags = intent?.tags || [];

	const bapTermsTag = tags.find(
		(tag) =>
			tag?.descriptor?.code ===
			"BAP_TERMS"
	);

	if (!bapTermsTag) {
		return {
			valid: false,
			code: 400,
			description:
				"BAP_TERMS tag missing",
		};
	}

	const incrementalPullTag =
		tags.find(
			(tag) =>
				tag?.descriptor?.code ===
				"INCREMENTAL_PULL"
		);

	// if (!incrementalPullTag) {
	// 	return {
	// 		valid: false,
	// 		code: 400,
	// 		description:
	// 			"INCREMENTAL_PULL tag missing",
