	);

	if (!bapTermsTag) {
		return {
			valid: false,
			code: 400,
			description:
				"BAP_TERMS tag missing",
		};
	}

	const incrementalPullTag =
		tags.find(
			(tag) =>
				tag?.descriptor?.code ===
				"INCREMENTAL_PULL"
		);

