		);

	if (!feePercentage) {
		return {
			valid: false,
			code: 400,
			description:
				"BUYER_FINDER_FEES_PERCENTAGE missing",
		};
	}

	return {
		valid: true,
		code: 200,
		description: "Valid request",
	};
